namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10-12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and plenty of black pepper.",
                    "Drain pasta, reserving 1 cup of pasta water.",
                    "Toss hot pasta with pancetta, then remove from heat.",
                    "Quickly stir in egg mixture, adding pasta water to create a creamy sauce."
                ],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                    "Grill or broil chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger in butter until softened.",
                    "Add spices and cook for 1 minute until fragrant.",
                    "Stir in tomato sauce and simmer for 15 minutes.",
                    "Add cream and chicken, simmer 10 more minutes."
                ],
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "A vibrant stir-fried noodle dish with a tangy tamarind sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Eggs", "Garlic"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, sugar, and lime juice for the sauce.",
                    "Press and cube tofu, then fry until golden.",
                    "Scramble eggs in the same pan and set aside.",
                    "Stir-fry garlic, add noodles and sauce, toss until coated.",
                    "Add tofu, eggs, bean sprouts, and top with peanuts and green onions."
                ],
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
                Steps = [
                    "Brown ground beef with diced onion in a skillet.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm taco shells in the oven for 3 minutes.",
                    "Fill shells with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, and sour cream."
                ],
                Ratings = [4, 3, 4, 5]
            },
            new Recipe
            {
                Id = 6, Title = "Green Curry", Category = "Thai",
                Description = "A fragrant coconut curry with vegetables and Thai basil.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken breast", "Bamboo shoots", "Thai basil", "Fish sauce", "Sugar", "Bell pepper", "Eggplant"],
                Steps = [
                    "Heat a splash of coconut milk in a wok until it separates.",
                    "Fry green curry paste for 2 minutes until fragrant.",
                    "Add remaining coconut milk and bring to a simmer.",
                    "Add sliced chicken and cook for 5 minutes.",
                    "Add vegetables and cook until tender.",
                    "Season with fish sauce and sugar, garnish with Thai basil."
                ],
                Ratings = [5, 4, 4, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt", "Garlic"],
                Steps = [
                    "Halve and pit the avocados, scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in lime juice, minced garlic, and salt.",
                    "Fold in diced onion, tomato, jalapeño, and cilantro.",
                    "Taste and adjust seasoning. Serve immediately with chips."
                ],
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Dal Tadka", Category = "Indian",
                Description = "Comforting spiced lentils tempered with cumin and ghee.",
                Ingredients = ["Yellow lentils (toor dal)", "Onion", "Tomato", "Garlic", "Cumin seeds", "Turmeric", "Red chili powder", "Ghee", "Cilantro"],
                Steps = [
                    "Wash lentils and cook with turmeric and water until soft.",
                    "In a separate pan, heat ghee and add cumin seeds.",
                    "Add chopped onion and garlic, sauté until golden.",
                    "Add tomatoes and spices, cook until tomatoes break down.",
                    "Pour the tempering over the cooked lentils and stir.",
                    "Garnish with fresh cilantro and serve with rice or naan."
                ],
                Ratings = [4, 5, 4]
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

