@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (HoverRating ?? SelectedRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = null"
              role="button"
              title="Rate @star star(s)">
            ★
        </span>
    }
    @if (SelectedRating > 0)
    {
        <span class="text-muted small">You rated @SelectedRating/5</span>
    }
    else
    {
        <span class="text-muted small">Click to rate</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }
    [Inject] private Services.RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating;
    private int? HoverRating;

    private async Task Rate(int rating)
    {
        SelectedRating = rating;
        RecipeService.AddRating(RecipeId, rating);
        await OnRated.InvokeAsync(rating);
    }
}

.star-rating .star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star-rating .star:hover {
    transform: scale(1.2);
}

.star-rating .star.filled {
    color: #f5a623;
}

@page "/"
@inject RecipeCommunity.Services.RecipeService RecipeService

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">🍳 Recipe Community</h1>
    <p class="lead text-muted">Discover and share delicious recipes from around the world</p>
</div>

<div class="row g-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        var recipes = RecipeService.GetByCategory(category);
        <div class="col-md-6 col-lg-3">
            <a href="category/@category" class="text-decoration-none">
                <div class="card h-100 shadow-sm category-card">
                    <div class="card-body text-center">
                        <div class="display-5 mb-3">@CategoryEmoji(category)</div>
                        <h3 class="card-title">@category</h3>
                        <p class="text-muted">@recipes.Count recipe(s)</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-5">
    <a href="submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🥘",
        "Mexican" => "🌮",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"
@inject RecipeCommunity.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row g-4">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">
                            <a href="recipe/@recipe.Id" class="text-decoration-none">@recipe.Title</a>
                        </h4>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="text-warning">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                }
                            </span>
                            <small class="text-muted">@recipe.AverageRating / 5 (@recipe.Ratings.Count ratings)</small>
                        </div>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe →</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeCommunity.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeCommunity.Services.RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe")</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@Recipe.Title</h1>
            <p class="lead text-muted">@Recipe.Description</p>

            <div class="mb-4 p-3 bg-light rounded">
                <strong>Average Rating:</strong>
                <span class="text-warning ms-2">
                    @for (int i = 1; i <= 5; i++)
                    {
                        <span>@(i <= (int)Math.Round(Recipe.AverageRating) ? "★" : "☆")</span>
                    }
                </span>
                <span class="text-muted ms-2">@Recipe.AverageRating / 5 (@Recipe.Ratings.Count ratings)</span>
            </div>

            <h3>📋 Ingredients</h3>
            <ul class="list-group list-group-flush mb-4">
                @foreach (var ingredient in Recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>

            <h3>👨‍🍳 Steps</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>

            <div class="card mb-4">
                <div class="card-body">
                    <h5 class="card-title">Rate this recipe</h5>
                    <StarRating RecipeId="Recipe.Id" OnRated="OnRated" />
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    private RecipeCommunity.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }

    private void OnRated(int rating)
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeCommunity.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe submitted!</h4>
        <p>Your recipe "<strong>@Submission.Title</strong>" has been added.</p>
        <a href="recipe/@NewRecipeId" class="btn btn-primary">View your recipe →</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="Submission.Title"
                               placeholder="e.g. Grandma's Chocolate Cake" />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat">@cat</option>
                        }
                        <option value="Other">Other</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="6"
                                   @bind-Value="Submission.Ingredients"
                                   placeholder="Enter one ingredient per line&#10;e.g.&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                    <div class="form-text">One ingredient per line</div>
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="8"
                                   @bind-Value="Submission.Steps"
                                   placeholder="Enter one step per line&#10;e.g.&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
                    <div class="form-text">One step per line</div>
                </div>

                <button type="submit" class="btn btn-success btn-lg"
                        disabled="@(!IsValid)">
